end;

      FUNCTION GET_PORT_NAME RETURN char IS
	V_PORT_NAME		VARCHAR2(100);
BEGIN
	TOOL_ENV.GETVAR('PORT_NAME',V_PORT_NAME);
	RETURN V_PORT_NAME;
END;

      function C_CODEFormula return Char is
C_NAME		VARCHAR2 (100) ;
begin
  SELECT CITY_ARB_NAME INTO C_NAME
  FROM CITIES 
  WHERE CITY_CD = :IMP_CITY_CODE
  AND   CTRY_CD = :CTRY_CD ;
  RETURN (C_NAME);
EXCEPTION
	WHEN NO_DATA_FOUND THEN 
	RETURN (NULL);
end;

      function C_PORT_CDFormula return Char is
	v_port  varchar2 (20) := 'الجمــــرك';
	R_VALUE CHAR(20) := 'المصلحة';
begin
  if :PORT_CD = 99 then
  	RETURN (R_VALUE);
  else
  	RETURN (V_PORT);
  	END IF ;
	end;

      function C_DATEFormula return Date is
H_DAT		DATE ;
begin
  H_DAT := HIJDATE.CUR_HIJ_DATE ;
  RETURN (H_DAT );

end;

      function TITFormula return Char is
TIT1	VARCHAR2 (50) := 'توقيفات المستوردين السارية';
TIT2	VARCHAR2 (50) := 'توقيفات المستوردين الغير سارية';
TIT3	VARCHAR2 (50) := 'توقيفات المستوردين السارية والغير سارية';
begin
  IF :P_TYPE = 3 THEN
  	RETURN (TIT3);
  ELSIF :P_TYPE = 2 THEN
  	RETURN (TIT2);
  ELSE
  	RETURN (TIT1);
  	END IF ;
end;

      function V_MEANFormula return Char is
H_DAT		DATE ;
begin
  H_DAT := HIJDATE.CUR_HIJ_DATE ;

  IF :SUSPN_RLSE_DT IS  NOT NULL THEN
  	RETURN ('  غير ساري  '); 
  ELSIF :SUSPN_RLSE_DT IS  NULL AND  H_DAT NOT BETWEEN :SUSPN_STRT_DT AND :SUSPN_END_DT THEN
  	RETURN (' غير ساري '); 
  ELSE
  	RETURN (' ساري ');
  END IF ;
end;

